package migrate

import (
	"database/sql"
	"fmt"
)

// Run adds the orders.status column and backfills it.
//
// It is safe to rerun after a partial failure: the column is only added if
// missing, and the backfill only touches orders whose status is still NULL,
// skipping events that were already written.
func Run(db *sql.DB) error {
	if err := addStatusColumn(db); err != nil {
		return fmt.Errorf("add column: %w", err)
	}
	if err := backfill(db); err != nil {
		return fmt.Errorf("backfill: %w", err)
	}
	return nil
}

func addStatusColumn(db *sql.DB) error {
	// Probe for the column; selecting it fails if it doesn't exist yet.
	if _, err := db.Exec(`SELECT status FROM orders LIMIT 0`); err == nil {
		return nil
	}
	_, err := db.Exec(`ALTER TABLE orders ADD COLUMN status TEXT`)
	return err
}

func backfill(db *sql.DB) error {
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// A previous run may have crashed between the insert and the update,
	// leaving an event for an order whose status is still NULL.
	if _, err := tx.Exec(`
		INSERT INTO order_events (order_id, kind)
		SELECT o.id, 'backfilled' FROM orders o
		WHERE o.status IS NULL
		  AND NOT EXISTS (
			SELECT 1 FROM order_events e
			WHERE e.order_id = o.id AND e.kind = 'backfilled'
		  )`); err != nil {
		return fmt.Errorf("insert events: %w", err)
	}
	if _, err := tx.Exec(`UPDATE orders SET status = 'open' WHERE status IS NULL`); err != nil {
		return fmt.Errorf("update status: %w", err)
	}
	return tx.Commit()
}

